import {lstat,readFile} from 'node:fs/promises';
const p=JSON.parse(process.env.PONDEROSA_PARAMETERS??'{}');
const name='pinecone-runtime-capability.json',s=await lstat(name);
if(!s.isFile()||s.isSymbolicLink()||s.size>8192)throw Error('Invalid runtime qualification evidence');
const q=JSON.parse(await readFile(name,'utf8'));
if(q.schema!==1||q.model!==p.requiredModel||q.effort!==p.requiredEffort||!Number.isFinite(Date.parse(q.verifiedAt))||Date.now()-Date.parse(q.verifiedAt)>86400000||Date.parse(q.verifiedAt)>Date.now()+60000)throw Error('Fresh qualification of the exact requested model and reasoning is required; no fallback permitted');
if(q.supported!==true)throw Error('Requested runtime unavailable; no fallback permitted. '+String(q.error??'Model access has not been verified').slice(0,1000));
let input='';for await(const c of process.stdin){input+=c;if(Buffer.byteLength(input)>262144)throw Error('Input too large');}process.stdout.write(input);

steps.instructions:
SHADOW EXPERIMENT: perform read-only research and complete only your correlated Request. Never call ponderosa_message, send email, author user_dm, notify, mutate connectors, create agents, or contact anyone. No outgoing messages are authorized. Do not read denied paths, sessions, credentials, private histories, or unrelated files. Read only the explicit candidate brief/ledger and narrow available authorized context. Missing access is an internal gap. Do not copy credentials or export personal memory. Public primary-source research is allowed. Do not edit the candidate files; scripts own the ledgers.
Read pinecone-context.md and coverage ledger. Form up to three grounded questions, choose one by benefit, novelty, coverage and cost, and actually research it even without incoming events. Rotate supported needs, opportunities and exploration. At most four public searches and six narrow context reads. Return at most 6 KiB evidence, dates, known facts, applicability, uncertainties, sources and one next step. Missing access does not prove absence.
Focus: {{parameter:focus}}

