import {readFile,writeFile,rename,lstat} from 'node:fs/promises';
import {createHash} from 'node:crypto';
let raw='';for await(const chunk of process.stdin){raw+=chunk;if(Buffer.byteLength(raw)>8192)throw Error('Finding exceeds 8 KiB');}
const report=JSON.parse(raw);
if(!report||typeof report!=='object'||Array.isArray(report)||typeof report.notify!=='boolean'||typeof report.question!=='string'||!report.question.trim()||report.question.length>500||typeof report.reason!=='string'||report.reason.length>1000)throw Error('Invalid discovery result');
if(report.notify&&(typeof report.claimKey!=='string'||!report.claimKey.trim()||report.claimKey.length>240||typeof report.topicKey!=='string'||!report.topicKey.trim()||report.topicKey.length>80||!report.relevance||!['research','email','memory'].includes(report.relevance.kind)||typeof report.relevance.reference!=='string'||!report.relevance.reference.trim()||report.relevance.reference.length>500||typeof report.relevance.observation!=='string'||!report.relevance.observation.trim()||report.relevance.observation.length>800||typeof report.message!=='string'||!report.message.trim()||report.message.length>1800||report.message.trim().split(/\s+/u).length>70||!Array.isArray(report.sources)||(report.relevance.kind==='research'&&!report.sources.length)||report.sources.length>2||report.sources.some(s=>{if(typeof s!=='string'||s.length>2000)return true;try{const url=new URL(s);return !['http:','https:'].includes(url.protocol)||!url.hostname||Boolean(url.username||url.password);}catch{return true;}})))throw Error('Finding needs bounded claim, message and sources');
if(report.notify){
 if(/https?:\/\/|www\.|@/iu.test(report.message))throw Error('Put links in sources, not message');
 report.message=report.message.trim().replace(/[\x21-\x2f\x3a-\x40\x5b-\x60\x7b-\x7e]/gu,'\\$&')+(report.sources.length?'\n\n'+report.sources.map((url,index)=>'[Source '+(index+1)+']('+new URL(url).href.replace(/\(/g,'%28').replace(/\)/g,'%29')+')').join(' · '):'');
 if(report.message.split(/\s+/u).length>70||report.message.length>6000)throw Error('Published finding exceeds message budget');
}
async function readLedger(){try{const stat=await lstat('pinecone-ledger.json');if(!stat.isFile()||stat.isSymbolicLink()||stat.size>32768)throw Error('Invalid coverage ledger');const ledger=JSON.parse(await readFile('pinecone-ledger.json','utf8'));if(ledger.schema!==1||!Array.isArray(ledger.checks)||ledger.checks.length>48||!Array.isArray(ledger.announced)||ledger.announced.length>100)throw Error('Invalid coverage ledger');return ledger;}catch(error){if(error.code==='ENOENT')return {schema:1,checks:[],announced:[]};throw error;}}
function boundLedger(ledger){while(Buffer.byteLength(JSON.stringify(ledger))>32768){if(ledger.checks.length>1)ledger.checks.shift();else if(ledger.shadowed.length)ledger.shadowed.shift();else if(ledger.announced.length)ledger.announced.shift();else throw Error('Coverage record exceeds byte budget');}return ledger;}
async function save(name,value){try{const stat=await lstat(name);if(!stat.isFile()||stat.isSymbolicLink())throw Error('Invalid discovery file');}catch(error){if(error.code!=='ENOENT')throw error;}const temp=name+'.'+process.pid+'.tmp';await writeFile(temp,JSON.stringify(value),{flag:'wx',mode:0o600});await rename(temp,name);}
const ledger=await readLedger(),now=new Date().toISOString();
ledger.shadowed??=[];
const feedbackStat=await lstat('pinecone-feedback.json');if(!feedbackStat.isFile()||feedbackStat.isSymbolicLink()||feedbackStat.size>32768)throw Error('Invalid feedback file');
const feedback=JSON.parse(await readFile('pinecone-feedback.json','utf8'));
const normalized=value=>typeof value==='string'?value.trim().toLowerCase():'';
if(feedback.schema!==1||!Array.isArray(feedback.items)||feedback.items.length>100)throw Error('Invalid explicit feedback');
let eligible=report.notify;
if(eligible){const a=report.assessment;if(!a||!['new','material_change'].includes(a.novelty)||a.state!=='active'||a.applicability!=='verified'||a.blockingUncertainty!==false||typeof a.fingerprint!=='string'||!a.fingerprint.trim()||a.fingerprint.length>240||!Number.isFinite(Date.parse(a.checkedAt))||Date.now()-Date.parse(a.checkedAt)>86400000||Date.parse(a.checkedAt)>Date.now()+60000||(a.novelty==='material_change'&&(!a.changeExplanation||a.changeExplanation.length>1000))){eligible=false;report.reason='Quiet: novelty, freshness, applicability, active state or uncertainty unverified';}else{const f=feedback.items.find(i=>normalized(i.claimKey)===normalized(report.claimKey)||(i.topicKey&&normalized(i.topicKey)===normalized(report.topicKey)));if(f&&!(a.novelty==='material_change'&&a.fingerprint!==f.fingerprint&&a.changeExplanation)){eligible=false;report.reason='Quiet: explicit known, dismissed or resolved feedback';}}}

ledger.checks=[...ledger.checks,{at:now,question:report.question,reason:report.reason,mode:'shadow',delivered:false}].slice(-48);
const key=report.notify?createHash('sha256').update(report.claimKey.trim().toLowerCase()).digest('hex'):undefined;
const topic=report.notify?createHash('sha256').update(report.topicKey.trim().toLowerCase()).digest('hex'):undefined;
const recent=[...ledger.announced,...ledger.shadowed].some(item=>Number.isFinite(Date.parse(item.at))&&Date.now()-Date.parse(item.at)<2*60*60*1000);
const repeatedTopic=[...ledger.announced,...ledger.shadowed].some(item=>item.topic===topic&&Number.isFinite(Date.parse(item.at))&&Date.now()-Date.parse(item.at)<24*60*60*1000);
const notify=eligible&&!recent&&!repeatedTopic&&![...ledger.announced,...ledger.shadowed].some(item=>item.key===key);
if(eligible&&!notify)ledger.checks[ledger.checks.length-1].reason='Held internally: '+(recent?'recent discovery already delivered':repeatedTopic?'same user need already covered':'claim already delivered');
await save('pinecone-ledger.json',boundLedger(ledger));
if(notify)await save('pinecone-finding.json',{...report,key,topic,createdAt:now});
process.stdout.write(notify?'notify':'quiet');

import {readFile,writeFile,rename} from 'node:fs/promises';
const ledger=JSON.parse(await readFile('pinecone-ledger.json','utf8')),f=JSON.parse(await readFile('pinecone-finding.json','utf8'));
if(!/^[a-f0-9]{64}$/.test(f.key)||!Array.isArray(ledger.announced))throw Error('Invalid shadow receipt');
ledger.shadowed=[...(ledger.shadowed??[]).filter(i=>i.key!==f.key),{key:f.key,topic:f.topic,at:new Date().toISOString(),delivered:false}].slice(-48);
const draft={mode:'shadow',delivered:false,communicationEventId:null,question:f.question,message:f.message,reason:f.reason};
await writeFile('pinecone-shadow-result.json',JSON.stringify(draft),{mode:0o600});
const temp='pinecone-ledger.json.'+process.pid+'.tmp';await writeFile(temp,JSON.stringify(ledger),{flag:'wx',mode:0o600});await rename(temp,'pinecone-ledger.json');process.stdout.write(JSON.stringify(draft));
